const lead = $('Fetch Lead from Supabase').first().json[0];
const painPoints = Array.isArray(lead.pain_points) ? lead.pain_points : JSON.parse(lead.pain_points || '[]');

const painDescriptions = {
  no_website: 'no tiene sitio web',
  slow_website: `su sitio web es muy lento (puntuación ${lead.website_speed_score}/100)`,
  no_ssl: 'su sitio web no tiene certificado SSL',
  not_mobile_friendly: 'su sitio web no está optimizado para móviles',
  no_booking: 'no tiene sistema de reservas online',
  few_reviews: `tiene muy pocas reseñas en Google (solo ${lead.reviews_count})`,
  low_rating: `tiene una calificación baja (${lead.rating} ⭐)`,
  no_meta_description: 'no tiene descripción SEO optimizada'
};

const painList = painPoints.slice(0, 3).map(p => `- ${painDescriptions[p] || p}`).join('
');

const systemPrompt = `Eres un experto en ventas digitales B2B especializado en vender servicios web y de IA a pequeños negocios locales en España.

Tu tarea es generar 3 scripts de venta CORTOS, DIRECTOS y MUY PERSONALIZADOS basados en los problemas reales detectados en el negocio.

REGLAS CRÍTICAS:
- Nunca mencionar que eres IA ni que has analizado su web automáticamente
- Usa siempre el nombre real del negocio
- Menciona SOLO los 1-2 problemas más importantes
- Tono: cercano, directo, como si fuera un mensaje de un profesional conocido
- NO uses saludos corporativos ("Estimado", "Me pongo en contacto")
- Email: máximo 120 palabras, asunto incluido
- WhatsApp: máximo 70 palabras, informal, emojis permitidos
- DM Instagram: máximo 50 palabras, muy casual

Responde SIEMPRE en JSON con este formato exacto (sin markdown, solo JSON puro):
{
  "ai_email": "Asunto: ...\n\nCuerpo del email...",
  "ai_whatsapp": "Texto del mensaje de WhatsApp...",
  "ai_dm": "Texto del DM de Instagram..."
}`;

const userPrompt = `Negocio: ${lead.name}
Sector: desconocido
Ubicación: desconocida
Calificación Google: ${lead.rating ?? 'sin dato'} ⭐ (${lead.reviews_count} reseñas)
Opportunity Score: ${lead.opportunity_score}/100

Problemas detectados:
${painList}

Genera los 3 scripts de venta personalizados para este negocio.`;

return [{ system: systemPrompt, user: userPrompt, lead_id: lead.id }];

const response = $input.first().json;
const content = response.choices?.[0]?.message?.content || '{}';
let scripts;
try {
  scripts = JSON.parse(content);
} catch {
  scripts = { ai_email: content, ai_whatsapp: content, ai_dm: content };
}
const leadId = $('Build OpenAI Prompt').first().json.lead_id;
return [{ ...scripts, lead_id: leadId }];

// When all leads in a search are done, update search status
// This is a simplified version - in production you'd check all leads
const searchRes = await $helpers.httpRequest({
  method: 'GET',
  url: `${process.env.SUPABASE_URL || $env.SUPABASE_URL}/rest/v1/leads?search_id=eq.${$('Fetch Lead from Supabase').first().json[0].search_id}&select=analysis_status`,
  headers: {
    apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
    Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`
  }
});

const allLeads = searchRes;
const allDone = allLeads.every(l => l.analysis_status === 'done' || l.analysis_status === 'failed');

if (allDone) {
  await $helpers.httpRequest({
    method: 'PATCH',
    url: `${$env.SUPABASE_URL}/rest/v1/searches?id=eq.${$('Fetch Lead from Supabase').first().json[0].search_id}`,
    headers: {
      apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
      Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ status: 'done' })
  });
}

return [{ ok: true, all_done: allDone }];
